<script setup lang="ts">
import RemoteProfiles from '../components/RemoteProfiles.vue';
import {computed} from 'vue';import {usePlatform} from '../stores/platform';import {filterRows,dataTypes} from '../domain';import QueryForm from '../components/QueryForm.vue';import DataTable from '../components/DataTable.vue';import type {Capture} from '../domain';import {apiMode} from '../api/client';
const p=usePlatform(),vehicle=computed(()=>p.active==='车码档案'),person=computed(()=>p.db.people.find(r=>r.id===p.detail?.id));
const profiles=computed(()=>apiMode==='http'?p.db.people.map(r=>({...r,kind:vehicle.value?'车辆档案':'人员档案',tags:[]})):p.db.people.map((r,i)=>({...r,target:vehicle.value?'示A'+(10000+i):r.target,kind:vehicle.value?'车辆档案':'人员档案',tags:p.db.models.filter(m=>{const days:Record<string,number>={};p.db.captures.filter(c=>c.person===r.id).forEach(c=>{const d=c.time.slice(0,10);days[d]=(days[d]||0)+1;});const dates=Object.keys(days).filter(d=>(days[d]||0)>=m.min).sort();let run=0;return m.enabled&&dates.some((d,i)=>{run=i&&new Date(d).getTime()-new Date(dates[i-1]||'').getTime()===86400000?run+1:1;return run>=m.days;});}).map(m=>m.label)})));
const rows=computed(()=>p.filterRows(profiles.value,p.f,{keyword:r=>r.name+' '+r.target+' '+r.appearance,tag:r=>r.tags.join(' ')}));const captures=computed(()=>p.captureRows().filter(c=>c.person===person.value?.id));
</script>
<template><RemoteProfiles v-if="apiMode==='http'"/><template v-else><template v-if="p.active==='数据态势'"><section class="card section-head"><h3>常驻数据模型库</h3><el-button type="primary" @click="p.formModel()">创建模型</el-button></section><DataTable :rows="p.db.models" :columns="[{key:'name',label:'模型名称',link:true},{key:'days',label:'连续出现天数'},{key:'min',label:'每日最少采集'},{key:'label',label:'数据标签'},{key:'enabled',label:'启用状态'}]" @open="row=>p.formModel(String(row.id))"/><QueryForm :model="p.f" :fields="[{key:'tag',label:'标签',options:['全部',...p.db.models.map(m=>m.label)]}]" @search="p.query" @reset="p.reset"/><DataTable :rows="rows" :columns="[{key:'name',label:'目标名称'},{key:'target',label:'特征码'},{key:'tags',label:'符合模型标签'}]" title="标签结果"/></template><template v-else-if="person"><section class="card"><div class="section-head"><h3>{{vehicle?'一车一档':'一人一档'}} · {{person.name}}</h3><el-button @click="p.dataAction('综合轨迹',captures)">综合轨迹查看</el-button></div><div class="profile-detail"><img v-if="person.image" :src="person.image" :alt="person.name"/><div v-else class="portrait-placeholder">画像待加载</div><dl><dt>{{vehicle?'车牌':'姓名'}}</dt><dd>{{vehicle?profiles.find(r=>r.id===person?.id)?.target:person.name}}</dd><dt>特征码</dt><dd>{{person.target}}</dd><dt>外貌特征</dt><dd>{{person.appearance}}</dd><dt>常驻地区</dt><dd>{{person.resident}}</dd><dt>疑似落脚点</dt><dd>{{person.landing}}</dd><dt>关联来源</dt><dd>{{apiMode==='mock'?'合成演示数据，不代表真实算法结果':'关联证据由后端档案接口提供'}}</dd></dl></div><el-tabs v-model="p.resultTab"><el-tab-pane v-for="type in dataTypes" :key="type" :label="type" :name="type"/></el-tabs></section><DataTable :rows="captures.filter(c=>c.type===p.resultTab)" :columns="[{key:'target',label:'关联目标'},{key:'type',label:'数据类型'},{key:'time',label:'采集时间'},{key:'site',label:'场所'},{key:'score',label:'演示关联度（%）'}]"><template #rowActions="{row}"><el-button link type="primary" @click="p.dataAction('检索',[row as Capture])">检索</el-button></template></DataTable></template><template v-else><QueryForm :model="p.f" :fields="[{key:'keyword',label:vehicle?'车牌 / 特征码':'外貌 / 特征码 / 姓名'},{key:'tag',label:'数据标签',options:['全部',...p.db.models.map(m=>m.label)]}]" @search="p.query" @reset="p.reset"/><section class="card"><h3>{{vehicle?'一车一档':'一人一档'}}归档</h3><div class="profile-gallery"><article v-for="r in rows" :key="r.id" class="profile-card"><img v-if="r.image" :src="r.image" :alt="r.name"/><div v-else class="portrait-placeholder">画像待加载</div><div><h3>{{vehicle?r.target:r.name}}</h3><p>{{r.target}}</p><p>{{r.appearance}}</p><el-tag v-for="tag in r.tags" :key="tag">{{tag}}</el-tag><div class="actions"><el-button @click="p.openDetail('profile',r.id)">基本资料 / 关联数据</el-button><el-button type="primary" @click="p.dataAction('综合轨迹',p.captureRows().filter(c=>c.person===r.id))">综合轨迹</el-button></div></div></article></div><el-empty v-if="!rows.length" description="无匹配档案"/></section></template></template></template>

